import React, { useEffect, useState } from 'react';
import api from '../services/api';

const tabs = [
  ['overview',  '📊 Vue d\'ensemble'],
  ['profs',     '👨‍🏫 Professeurs'],
  ['demandes',  '💡 Demandes Matières'],
  ['referentiel','📚 Référentiel'],
];

export default function Admin() {
  const [tab, setTab]           = useState('overview');
  const [stats, setStats]       = useState({});
  const [profs, setProfs]       = useState([]);
  const [pending, setPending]   = useState([]);
  const [structure, setStructure] = useState([]);
  const [villes, setVilles]     = useState([]);
  const [demandes, setDemandes] = useState([]);
  const [loading, setLoading]   = useState(true);

  const [showAddMat, setShowAddMat] = useState(false);
  const [newMat, setNewMat]         = useState({ nom: '', niveau_id: '' });

  useEffect(() => { loadAllData(); }, []);

  const loadAllData = async () => {
    setLoading(true);
    try {
      const [s, p, pend, struct, v, dem] = await Promise.all([
        api.get('/api/admin/stats'),
        api.get('/api/professeurs/'),
        api.get('/api/admin/professeurs/pending'),
        api.get('/api/admin/referentiel/structure'),
        api.get('/api/admin/referentiel/villes'),
        api.get('/api/admin/demandes-matieres'),
      ]);
      setStats(s.data);
      setProfs(p.data);
      setPending(pend.data);
      setStructure(struct.data);
      setVilles(v.data);
      setDemandes(dem.data);
    } catch (err) {
      console.error('Erreur chargement admin', err);
    } finally {
      setLoading(false);
    }
  };

  const handleValider = async (id) => {
    await api.put(`/api/admin/professeurs/${id}/valider`);
    alert('✅ Professeur validé');
    loadAllData();
  };

  const handleAddMatiere = async (e) => {
    e.preventDefault();
    await api.post('/api/admin/referentiel/matieres', newMat);
    setShowAddMat(false);
    setNewMat({ nom: '', niveau_id: '' });
    loadAllData();
  };

  const handleApprouverDemande = async (id) => {
    try {
      await api.put(`/api/admin/demandes-matieres/${id}/approuver`);
      alert('✅ Matière approuvée et ajoutée au référentiel !');
      loadAllData();
    } catch (e) {
      alert('Erreur : ' + (e.response?.data?.detail || e.message));
    }
  };

  const handleRefuserDemande = async (id) => {
    if (!window.confirm('Refuser cette demande ?')) return;
    try {
      await api.put(`/api/admin/demandes-matieres/${id}/refuser`);
      loadAllData();
    } catch (e) {
      alert('Erreur : ' + (e.response?.data?.detail || e.message));
    }
  };

  /* ── Helpers UI ── */
  const tabStyle = (t) => ({
    flex: 1, padding: '11px', textAlign: 'center', borderRadius: 12,
    cursor: 'pointer', fontWeight: 600, fontSize: '.88rem', transition: '.2s',
    background: tab === t ? '#6c63ff' : 'transparent',
    color: tab === t ? '#fff' : 'var(--text2)', border: 'none',
    position: 'relative',
  });

  const demandesPending = demandes.filter(d => d.statut === 'en_attente').length;

  const StatutBadge = ({ statut }) => {
    const cfg = {
      en_attente: { bg: 'rgba(245,158,11,0.12)', color: '#f59e0b', label: '⏳ En attente' },
      approuvé:   { bg: 'rgba(67,233,123,0.12)',  color: '#43e97b', label: '✅ Approuvée' },
      refusé:     { bg: 'rgba(255,101,132,0.12)', color: '#ff6584', label: '❌ Refusée'  },
    }[statut] || { bg: 'var(--surface2)', color: 'var(--text2)', label: statut };
    return (
      <span style={{ fontSize: '.72rem', fontWeight: 700, padding: '3px 10px', borderRadius: 20, background: cfg.bg, color: cfg.color }}>
        {cfg.label}
      </span>
    );
  };

  const statCards = [
    { icon: '👥', val: stats.total_users        || 0, lbl: 'Utilisateurs',    color: '#6c63ff', bg: 'rgba(108,99,255,.1)'  },
    { icon: '👨‍🏫', val: stats.total_professeurs  || 0, lbl: 'Profs validés',   color: '#43e97b', bg: 'rgba(67,233,123,.1)'  },
    { icon: '⏳', val: stats.en_attente          || 0, lbl: 'En attente',      color: '#f59e0b', bg: 'rgba(245,158,11,.1)'  },
    { icon: '📅', val: stats.total_reservations  || 0, lbl: 'Réservations',    color: '#38bdf8', bg: 'rgba(56,189,248,.1)'  },
    { icon: '💡', val: stats.demandes_matieres_pending || 0, lbl: 'Demandes matières', color: '#ff6584', bg: 'rgba(255,101,132,.1)' },
  ];

  return (
    <div style={{ padding: 32, maxWidth: 1200, margin: '0 auto' }}>
      <div style={{ fontFamily: 'Syne', fontSize: '1.8rem', fontWeight: 800, marginBottom: 32 }}>
        🛠 Dashboard Admin
      </div>

      {/* ── STATS ── */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(5,1fr)', gap: 16, marginBottom: 32 }}>
        {statCards.map(s => (
          <div key={s.lbl} style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 20 }}>
            <div style={{ width: 44, height: 44, borderRadius: 12, background: s.bg, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.2rem', marginBottom: 14 }}>{s.icon}</div>
            <div style={{ fontFamily: 'Syne', fontSize: '1.7rem', fontWeight: 800, color: s.color }}>{s.val}</div>
            <div style={{ fontSize: '.8rem', color: 'var(--text2)' }}>{s.lbl}</div>
          </div>
        ))}
      </div>

      {/* ── ONGLETS ── */}
      <div style={{ display: 'flex', background: 'var(--surface2)', borderRadius: 16, padding: 6, marginBottom: 32, gap: 4 }}>
        {tabs.map(([k, l]) => (
          <button key={k} style={tabStyle(k)} onClick={() => setTab(k)}>
            {l}
            {/* Badge rouge sur l'onglet Demandes si en attente */}
            {k === 'demandes' && demandesPending > 0 && (
              <span style={{ position: 'absolute', top: 4, right: 8, background: '#ff6584', color: '#fff', fontSize: '.6rem', fontWeight: 800, padding: '1px 6px', borderRadius: 20, minWidth: 18, textAlign: 'center' }}>
                {demandesPending}
              </span>
            )}
          </button>
        ))}
      </div>

      {/* ════════════════════════════════════════
          ONGLET : VUE D'ENSEMBLE
      ════════════════════════════════════════ */}
      {tab === 'overview' && (
        <div style={{ display: 'grid', gridTemplateColumns: '1.2fr 0.8fr', gap: 24 }}>
          <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
            <div style={{ fontWeight: 700, marginBottom: 20 }}>📊 Activité récente</div>
            <p style={{ color: 'var(--text2)' }}>{stats.reservations_mois} nouvelles réservations ce mois-ci.</p>
            {demandesPending > 0 && (
              <div
                onClick={() => setTab('demandes')}
                style={{ marginTop: 16, padding: '12px 16px', background: 'rgba(255,101,132,0.08)', border: '1px solid rgba(255,101,132,0.25)', borderRadius: 12, cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 10 }}
              >
                <span style={{ fontSize: '1.2rem' }}>💡</span>
                <div>
                  <div style={{ fontWeight: 700, fontSize: '.88rem', color: '#ff6584' }}>
                    {demandesPending} demande{demandesPending > 1 ? 's' : ''} de matière{demandesPending > 1 ? 's' : ''} en attente
                  </div>
                  <div style={{ fontSize: '.75rem', color: 'var(--text2)' }}>Cliquez pour examiner</div>
                </div>
              </div>
            )}
          </div>
          <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
            <div style={{ fontWeight: 700, marginBottom: 20 }}>🏆 Top Professeurs</div>
            {profs.slice(0, 4).map(p => (
              <div key={p.id} style={{ display: 'flex', justifyContent: 'space-between', padding: '12px 0', borderBottom: '1px solid var(--border)' }}>
                <span style={{ fontSize: '.9rem' }}>{p.user_nom} {p.user_prenom}</span>
                <span style={{ color: '#f59e0b', fontWeight: 700 }}>★ {p.note_moyenne}</span>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* ════════════════════════════════════════
          ONGLET : PROFESSEURS
      ════════════════════════════════════════ */}
      {tab === 'profs' && (
        <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
          <h3 style={{ marginBottom: 24, marginTop: 0 }}>👨‍🏫 Gestion des Professeurs</h3>

          {pending.length > 0 && (
            <div style={{ marginBottom: 32 }}>
              <div style={{ color: '#f59e0b', fontWeight: 700, fontSize: '.88rem', marginBottom: 12 }}>
                ⚠️ EN ATTENTE DE VALIDATION ({pending.length})
              </div>
              {pending.map(p => (
                <div key={p.id} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: 16, background: 'rgba(245,158,11,0.05)', border: '1px solid rgba(245,158,11,0.2)', borderRadius: 16, marginBottom: 10 }}>
                  <div>
                    <div style={{ fontWeight: 700 }}>{p.nom}</div>
                    <div style={{ fontSize: '.8rem', color: 'var(--text2)' }}>{p.email}</div>
                  </div>
                  <div style={{ display: 'flex', gap: 10 }}>
                    <button onClick={() => handleValider(p.id)} style={{ padding: '8px 16px', background: '#43e97b', color: '#000', border: 'none', borderRadius: 10, fontWeight: 700, cursor: 'pointer' }}>Valider</button>
                    <button style={{ padding: '8px 16px', background: 'transparent', color: '#ff6584', border: '1px solid #ff6584', borderRadius: 10, fontWeight: 600, cursor: 'pointer' }}>Refuser</button>
                  </div>
                </div>
              ))}
            </div>
          )}

          <table style={{ width: '100%', borderCollapse: 'collapse' }}>
            <thead>
              <tr style={{ textAlign: 'left', color: 'var(--text2)', fontSize: '.8rem', borderBottom: '1px solid var(--border)' }}>
                <th style={{ padding: 12 }}>PROFESSEUR</th>
                <th style={{ padding: 12 }}>VILLE</th>
                <th style={{ padding: 12 }}>MODE</th>
                <th style={{ padding: 12 }}>STATUT</th>
                <th style={{ padding: 12 }}>ACTION</th>
              </tr>
            </thead>
            <tbody>
              {profs.map(p => (
                <tr key={p.id} style={{ borderBottom: '1px solid var(--border)' }}>
                  <td style={{ padding: 12, fontWeight: 600 }}>{p.user_nom} {p.user_prenom}</td>
                  <td style={{ padding: 12 }}>{p.ville}</td>
                  <td style={{ padding: 12, fontSize: '.8rem' }}>
                    {p.mode_enseignement === 'en_ligne' ? '🌐 En ligne' : p.mode_enseignement === 'presentiel' ? '🏫 Présentiel' : '🔀 Les deux'}
                  </td>
                  <td style={{ padding: 12 }}>
                    <span style={{ padding: '4px 10px', borderRadius: 20, fontSize: '.7rem', fontWeight: 800, background: p.statut_validation === 'validé' ? 'rgba(67,233,123,0.1)' : 'rgba(245,158,11,0.1)', color: p.statut_validation === 'validé' ? '#43e97b' : '#f59e0b' }}>
                      {p.statut_validation?.toUpperCase()}
                    </span>
                  </td>
                  <td style={{ padding: 12 }}>
                    <button style={{ background: 'none', border: 'none', cursor: 'pointer', fontSize: '1rem' }}>🗑️</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {/* ════════════════════════════════════════
          ONGLET : DEMANDES MATIÈRES (NOUVEAU)
      ════════════════════════════════════════ */}
      {tab === 'demandes' && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 24 }}>

          {/* Résumé */}
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3,1fr)', gap: 16 }}>
            {[
              { label: 'En attente', count: demandes.filter(d => d.statut === 'en_attente').length, color: '#f59e0b', bg: 'rgba(245,158,11,0.1)' },
              { label: 'Approuvées', count: demandes.filter(d => d.statut === 'approuvé').length,   color: '#43e97b', bg: 'rgba(67,233,123,0.1)'  },
              { label: 'Refusées',   count: demandes.filter(d => d.statut === 'refusé').length,     color: '#ff6584', bg: 'rgba(255,101,132,0.1)' },
            ].map(s => (
              <div key={s.label} style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 16, padding: '16px 20px', display: 'flex', alignItems: 'center', gap: 14 }}>
                <div style={{ width: 44, height: 44, borderRadius: 12, background: s.bg, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                  <span style={{ fontFamily: 'Syne', fontSize: '1.3rem', fontWeight: 800, color: s.color }}>{s.count}</span>
                </div>
                <div style={{ fontSize: '.85rem', color: 'var(--text2)', fontWeight: 600 }}>{s.label}</div>
              </div>
            ))}
          </div>

          {/* Liste des demandes EN ATTENTE */}
          {demandes.filter(d => d.statut === 'en_attente').length > 0 && (
            <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
              <h3 style={{ marginTop: 0, marginBottom: 20, color: '#f59e0b' }}>⏳ Demandes en attente</h3>
              <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
                {demandes.filter(d => d.statut === 'en_attente').map(d => (
                  <div
                    key={d.id}
                    style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '16px 20px', background: 'rgba(245,158,11,0.05)', border: '1px solid rgba(245,158,11,0.2)', borderRadius: 14 }}
                  >
                    <div style={{ flex: 1 }}>
                      {/* Nom matière */}
                      <div style={{ fontWeight: 700, fontSize: '1rem', marginBottom: 4 }}>
                        💡 {d.nom_matiere}
                      </div>
                      {/* Niveau */}
                      <div style={{ display: 'flex', gap: 12, fontSize: '.8rem', color: 'var(--text2)' }}>
                        <span>🎓 {d.nom_niveau}</span>
                        <span>👨‍🏫 {d.prof_nom}</span>
                        <span>🕐 {new Date(d.created_at).toLocaleDateString('fr-FR')}</span>
                      </div>
                    </div>
                    <div style={{ display: 'flex', gap: 10, flexShrink: 0 }}>
                      <button
                        onClick={() => handleApprouverDemande(d.id)}
                        style={{ padding: '9px 18px', background: 'linear-gradient(135deg,#43e97b,#38f9d7)', color: '#000', border: 'none', borderRadius: 10, fontWeight: 700, cursor: 'pointer', fontSize: '.85rem' }}
                      >
                        ✅ Approuver
                      </button>
                      <button
                        onClick={() => handleRefuserDemande(d.id)}
                        style={{ padding: '9px 18px', background: 'transparent', color: '#ff6584', border: '1px solid #ff6584', borderRadius: 10, fontWeight: 600, cursor: 'pointer', fontSize: '.85rem' }}
                      >
                        ❌ Refuser
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {demandes.filter(d => d.statut === 'en_attente').length === 0 && (
            <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 40, textAlign: 'center', color: 'var(--text2)' }}>
              <div style={{ fontSize: '2rem', marginBottom: 10 }}>✅</div>
              <div style={{ fontWeight: 600 }}>Aucune demande en attente</div>
              <div style={{ fontSize: '.82rem', marginTop: 4 }}>Toutes les demandes ont été traitées</div>
            </div>
          )}

          {/* Historique (approuvées + refusées) */}
          {demandes.filter(d => d.statut !== 'en_attente').length > 0 && (
            <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
              <h3 style={{ marginTop: 0, marginBottom: 20 }}>📋 Historique des demandes traitées</h3>
              <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                <thead>
                  <tr style={{ textAlign: 'left', color: 'var(--text2)', fontSize: '.78rem', borderBottom: '1px solid var(--border)' }}>
                    <th style={{ padding: '10px 12px' }}>MATIÈRE</th>
                    <th style={{ padding: '10px 12px' }}>NIVEAU</th>
                    <th style={{ padding: '10px 12px' }}>PROFESSEUR</th>
                    <th style={{ padding: '10px 12px' }}>DATE</th>
                    <th style={{ padding: '10px 12px' }}>STATUT</th>
                  </tr>
                </thead>
                <tbody>
                  {demandes.filter(d => d.statut !== 'en_attente').map(d => (
                    <tr key={d.id} style={{ borderBottom: '1px solid var(--border)' }}>
                      <td style={{ padding: '12px', fontWeight: 600 }}>{d.nom_matiere}</td>
                      <td style={{ padding: '12px', fontSize: '.85rem', color: 'var(--text2)' }}>{d.nom_niveau}</td>
                      <td style={{ padding: '12px', fontSize: '.85rem' }}>{d.prof_nom}</td>
                      <td style={{ padding: '12px', fontSize: '.82rem', color: 'var(--text2)' }}>
                        {new Date(d.created_at).toLocaleDateString('fr-FR')}
                      </td>
                      <td style={{ padding: '12px' }}><StatutBadge statut={d.statut} /></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}

      {/* ════════════════════════════════════════
          ONGLET : RÉFÉRENTIEL
      ════════════════════════════════════════ */}
      {tab === 'referentiel' && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 32 }}>

          {/* Villes */}
          <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 20 }}>
              <h3 style={{ fontFamily: 'Syne', margin: 0 }}>📍 Villes actives</h3>
              <button style={{ background: 'var(--surface2)', color: 'var(--text)', border: '1px solid var(--border)', padding: '6px 14px', borderRadius: 8, cursor: 'pointer' }}>+ Ajouter</button>
            </div>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 10 }}>
              {villes.map(v => (
                <span key={v.id} style={{ background: 'var(--surface2)', padding: '8px 16px', borderRadius: 12, border: '1px solid var(--border)', fontSize: '.9rem' }}>{v.nom}</span>
              ))}
            </div>
          </div>

          {/* Structure Domaine > Niveau > Matière */}
          {structure.map(dom => (
            <div key={dom.id} style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
              <h3 style={{ color: '#6c63ff', fontFamily: 'Syne', marginBottom: 24, marginTop: 0, fontSize: '1.3rem' }}>
                📁 {dom.nom}
              </h3>
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 20 }}>
                {dom.niveaux?.map(niv => (
                  <div key={niv.id} style={{ background: 'var(--surface2)', padding: 18, borderRadius: 16, border: '1px solid var(--border)' }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 14, borderBottom: '1px solid var(--border)', paddingBottom: 10 }}>
                      <span style={{ fontWeight: 800, fontSize: '.9rem' }}>🎓 {niv.nom}</span>
                      <button
                        onClick={() => { setNewMat({ ...newMat, niveau_id: niv.id }); setShowAddMat(true); }}
                        style={{ background: 'none', border: 'none', color: '#6c63ff', cursor: 'pointer', fontWeight: 700, fontSize: '.78rem' }}
                      >+ AJOUTER</button>
                    </div>
                    <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
                      {niv.matieres?.map(m => (
                        <div key={m.id} style={{ background: 'var(--card)', padding: '6px 12px', borderRadius: 8, fontSize: '.8rem', border: '1px solid var(--border)', display: 'flex', gap: 8, alignItems: 'center' }}>
                          {m.nom}
                          <span style={{ color: '#ff6584', cursor: 'pointer', fontSize: '.75rem' }}>✕</span>
                        </div>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      )}

      {/* MODALE AJOUT MATIÈRE (référentiel direct) */}
      {showAddMat && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.8)', zIndex: 1000, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
          <div style={{ background: 'var(--surface)', padding: 32, borderRadius: 24, width: 400, border: '1px solid var(--border)' }}>
            <h3 style={{ marginBottom: 20, marginTop: 0 }}>Nouvelle matière</h3>
            <form onSubmit={handleAddMatiere} style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
              <input
                style={{ width: '100%', background: 'var(--surface2)', border: '1px solid var(--border)', padding: 12, borderRadius: 10, color: '#fff', outline: 'none' }}
                placeholder="Nom de la matière (ex: Algorithmique)"
                value={newMat.nom}
                onChange={e => setNewMat({ ...newMat, nom: e.target.value })}
                required
              />
              <div style={{ display: 'flex', gap: 10 }}>
                <button type="submit" style={{ flex: 2, background: '#6c63ff', color: '#fff', border: 'none', padding: 12, borderRadius: 10, fontWeight: 700, cursor: 'pointer' }}>Enregistrer</button>
                <button type="button" onClick={() => setShowAddMat(false)} style={{ flex: 1, background: 'var(--surface2)', color: '#fff', border: 'none', padding: 12, borderRadius: 10, cursor: 'pointer' }}>Annuler</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}
